# =============================================================================
# Policy Priorities: a benefit-cost ranking of 40 policies
# Tyler Young · Lighthearted Humans thesis project
#
# Runs as a normal Shiny app in RStudio (Run App) and is exported to the
# website with shinylive (see R/03_export_dashboard.R), where it runs entirely
# in the visitor's browser. Base R graphics and plain HTML tables only (no
# ggplot2 or DT), so the browser has far less to download.
# =============================================================================

library(shiny)
library(bslib)

source("bca_engine.R")
pol <- read.csv("policies.csv", stringsAsFactors = FALSE)
src <- read.csv("sources.csv", stringsAsFactors = FALSE)

cats <- sort(unique(pol$category))
esc  <- function(x) htmltools::htmlEscape(ifelse(is.na(x), "", as.character(x)))
fmt_bcr <- function(x) ifelse(is.na(x), "—",
                       ifelse(abs(x) >= 100, formatC(x, format = "f", digits = 0, big.mark = ","),
                       ifelse(abs(x) >= 10, formatC(x, format = "f", digits = 1),
                                            formatC(x, format = "f", digits = 2))))
fmt_bn <- function(x) ifelse(is.na(x), "—",
                      ifelse(x < 0, paste0("saves $", trimws(formatC(-x, format = "fg", digits = 3, big.mark = ",")), "B"),
                      ifelse(x == 0, "$0",
                      ifelse(x >= 1000, paste0("$", formatC(x / 1000, format = "f", digits = 1), "T"),
                                        paste0("$", trimws(formatC(x, format = "fg", digits = 3, big.mark = ",")), "B")))))
fmt_pct <- function(x) paste0(round(100 * x), "%")
badge <- function(g) sprintf('<span class="gb" style="background:%s;color:%s">%s</span>', GRADE_COLS[g],
                             ifelse(g %in% c("A-", "B+", "B", "B-", "C-"), "#2d3a4a", "#ffffff"), esc(g))
src_link <- function(url, doi) {
  u <- ifelse(!is.na(doi) & nzchar(doi), paste0("https://doi.org/", sub("^https?://(dx\\.)?doi\\.org/", "", doi)), url)
  ifelse(is.na(u) | !nzchar(u), "", sprintf(' <a href="%s" target="_blank" rel="noopener">link</a>', esc(u)))
}
DIFF_COLS <- c(easy = unname(PAL["blue"]), moderate = unname(PAL["yellow"]), hard = unname(PAL["red"]))
WHO_LABEL <- c(`pro-poor` = "Mostly the poor", broad = "Everyone", regressive = "Mostly the better-off")
TYPE_LABEL <- c(peer_reviewed = "Peer-reviewed", book = "Book", working_paper = "Working paper",
                think_tank = "Think tank", government = "Government", intl_org = "International body")

# ---- Grading rubric (shown on the Uncertainty tab; used for every grade) ----
RUBRIC <- list(
  c("A+", "Several peer-reviewed benefit-cost studies, including randomized or controlled trials, with consistent, statistically significant results."),
  c("A",  "Peer-reviewed benefit-cost estimates backed by controlled or quasi-experimental studies."),
  c("A-", "One peer-reviewed benefit-cost estimate, or a peer-reviewed meta-analysis whose effects convert directly into a benefit-cost ratio."),
  c("B+", "Peer-reviewed natural experiments or historical comparisons that measure the size of the gain (GDP, welfare, prices, lives), converted into a ratio."),
  c("B",  "Published economic theory in peer-reviewed journals or academic books, supported by historical cases and quantified in published models."),
  c("B-", "Official estimates from government or international bodies (CBO, GAO, IMF, OECD, World Bank, regulators' own impact analyses)."),
  c("C+", "Think-tank studies with stated methods and numbers (Cato, Mercatus, Heritage, Tax Foundation, AEI, Reason, IEA, Fraser and others)."),
  c("C",  "Books and published arguments by economists with historical illustrations, where the numbers come from think-tank or secondary estimates."),
  c("C-", "Published theory only: never tried at scale, and the ratio is built by analogy from related evidence.")
)
grade_key <- function(extra = NULL) div(class = "gkey",
  div(class = "gkey-t", "Colour = evidence grade: how strong the published evidence behind each number is"),
  div(class = "gkey-row",
    span(class = "gkey-end", "Strongest"),
    HTML(paste(vapply(GRADES, badge, ""), collapse = " ")),
    span(class = "gkey-end", "Weakest")),
  div(class = "gkey-s", HTML("<b>A</b> grades = peer-reviewed benefit-cost studies, the best with randomized or controlled trials &nbsp;\u00b7&nbsp; <b>B</b> grades = natural experiments, published economic models and official estimates &nbsp;\u00b7&nbsp; <b>C</b> grades = think-tank studies and theory, down to C\u2212: never tried at scale. Full rubric on the Uncertainty tab.")),
  extra)
rubric_ui <- tags$ol(class = "rubric", lapply(RUBRIC, function(r)
  tags$li(HTML(badge(r[1])), " ", r[2])))

# ---- Context budgets (Budget tab) ---------------------------------------------------
# Headline budget: official development aid (OECD Development Assistance
# Committee donors; the UN uses the same OECD figures).
ODA <- c(`2023` = 223.7, `2024` = 214.6, `2025` = 174.3, `2026` = 174.3 * (1 - 0.058))
AVAIL_YR <- ODA[["2025"]]     # latest actual year

CONTEXT <- data.frame(
  what = c("Global fossil-fuel subsidies, 2024 (explicit $725B plus unpriced pollution and climate costs)",
           "UN estimate of the yearly gap to fund the Sustainable Development Goals (2026 report)",
           "Global climate finance, 2025 (estimate)",
           "Official development aid from rich-country donors, 2025",
           "World Bank Group lending commitments to partner countries, fiscal 2025",
           "US official development aid, 2025 (down 57% from 2024)"),
  bn = c(7400, 4000, 2100, ODA[["2025"]], 118.5, 29.0),
  source = c("IMF Working Paper 25/270 (2025 update)", "UN Financing for Sustainable Development Report 2026",
             "Climate Policy Initiative, Global Landscape of Climate Finance 2026", "OECD, preliminary 2025 ODA data (April 2026)",
             "World Bank Group Annual Report 2025", "OECD, preliminary 2025 ODA data (April 2026)"),
  url = c("https://www.elibrary.imf.org/view/journals/001/2025/270/article-A001-en.xml",
          "https://desapublications.un.org/publications/financing-sustainable-development-report-2026",
          "https://glcf.climatepolicyinitiative.org/",
          "https://www.oecd.org/en/data/insights/data-explainers/2026/04/a-historic-decline-in-foreign-aid-preliminary-2025-oda-data.html",
          "https://www.worldbank.org/en/about/annual-report/financial-summary",
          "https://www.oecd.org/en/data/insights/data-explainers/2026/04/a-historic-decline-in-foreign-aid-preliminary-2025-oda-data.html"),
  stringsAsFactors = FALSE)
context_ui <- local({
  mx <- log10(max(CONTEXT$bn))
  rows <- vapply(seq_len(nrow(CONTEXT)), function(i) sprintf(
    '<tr><td>%s<div class="small-src"><a href="%s" target="_blank" rel="noopener">%s</a></div></td><td class="num">%s</td><td class="barcell"><div class="bar" style="width:%.0f%%"></div></td></tr>',
    esc(CONTEXT$what[i]), CONTEXT$url[i], esc(CONTEXT$source[i]), fmt_bn(CONTEXT$bn[i]),
    100 * log10(CONTEXT$bn[i]) / mx), character(1))
  avail <- sprintf('<tr class="hl"><td><b>Development aid budget (headline)</b><div class="small-src">OECD, preliminary 2025 data</div></td><td class="num"><b>%s</b></td><td class="barcell"><div class="bar hlbar" style="width:%.0f%%"></div></td></tr>',
                   fmt_bn(AVAIL_YR), 100 * log10(AVAIL_YR) / mx)
  HTML(paste0('<div class="tscroll"><table class="tbl"><thead><tr><th>Budget</th><th class="num">Per year</th><th>Size (log scale)</th></tr></thead><tbody>',
              paste(c(rows, avail), collapse = ""), "</tbody></table></div>"))
})

# ---- Bibliography (All sources tab) --------------------------------------------------
bib_ui <- local({
  u <- src[!duplicated(tolower(paste(src$title, src$year))), ]
  key <- tolower(ifelse(is.na(u$authors) | !nzchar(u$authors), u$title, u$authors))
  u <- u[order(gsub("[^a-z0-9 ]", "", key)), ]
  lines <- sprintf('<p class="bib">%s (%s). %s. <em>%s</em>.%s</p>',
                   esc(ifelse(is.na(u$authors), "", u$authors)), esc(ifelse(is.na(u$year), "n.d.", u$year)),
                   esc(u$title), esc(u$venue), src_link(u$url, u$doi))
  tagList(p(class = "lead-sm", sprintf("%d unique works cited across the 40 policies, in alphabetical order.", nrow(u))),
          HTML(paste(lines, collapse = "\n")))
})

# ---- UI ------------------------------------------------------------------------
ctl <- function(widget, help) div(class = "ctl", widget, div(class = "help", help))
# A 0-1 slider with a label under each end
ends <- function(id, label, left, right, help, value = 0.5)
  div(class = "ctl", sliderInput(id, label, 0, 1, value, 0.05, ticks = FALSE),
      div(class = "ends", span(left), span(right)), div(class = "help", help))

controls <- sidebar(
  width = 320,
  actionButton("reset", "RESET", class = "resetbtn", width = "100%"),
  div(class = "help", style = "text-align:center;margin-top:.25rem", "Reset to final published priority ranking"),
  div(class = "help top", "Every number comes from published sources. Move a dial and the whole dashboard re-ranks."),
  h6("Evidence & time"),
  ends("skep", "Evidence skepticism", "C\u2212 \u00b7 All data", "A+ \u00b7 Best data",
       "Left takes every published number at face value; right trusts the strongest evidence most and pulls weaker numbers toward break-even (1:1)."),
  ctl(sliderInput("rate", "Discount rate (%)", 0, 10, 5, 0.5),
      "How much less a benefit is worth for each year you wait; most studies use 3\u20138%, and 5% leaves them unchanged. If you anticipate higher inflation, the discount rate goes up."),
  h6("Tilt the ranking (middle = no tilt)"),
  div(class = "help", "The benefit-cost ratio always counts in full. These dials only add a tilt toward one side; at the middle they have no effect."),
  ends("t_equity", "Helps the poor", "Benefits the poor", "Benefits higher income",
       "Move left to favour policies whose gains go mostly to the poorest; right to favour those that mostly help higher incomes."),
  ends("t_feas", "Feasibility", "Difficult", "Easy",
       "Move right to favour policies the sources show are easy to put in place; left to favour the hard ones."),
  ends("t_cost", "Low cost", "Cheap", "Expensive",
       "Move left to favour policies that cost little per year; right to favour the big-ticket ones. This affects the total weight but does not mean the winning policies are more or less expensive."),
  div(class = "help fixed", HTML("<b>Uncertainty:</b> each policy's ratio is drawn 1,000 times from its published range (a Monte Carlo simulation), and every chart shows the middle result and the range."))
)

CSS <- "
body{font-family:Georgia,'Times New Roman',serif}
.help{font-size:.76rem;line-height:1.25;color:#667;margin:-.6rem 0 .9rem}
.help.top{margin:0 0 .8rem;font-style:italic}
.help.fixed{margin-top:.4rem;border-top:1px solid #ddd;padding-top:.6rem}
.sidebar h6{margin:.6rem 0 .5rem;text-transform:uppercase;letter-spacing:.06em;font-size:.72rem;color:#3d6fd6;font-family:system-ui,sans-serif}
.ends{display:flex;justify-content:space-between;font:600 .7rem system-ui,sans-serif;color:#4a5566;margin:-.55rem 0 .7rem}
.irs--shiny .irs-bar{background:#8db0f3;border-color:#8db0f3}
.irs--shiny .irs-single,.irs--shiny .irs-handle{background:#5b8def;border-color:#5b8def}
.irs--shiny .irs-handle:hover{background:#3d6fd6}
a{color:#3d6fd6}
.navbar .navbar-toggler{display:none !important}
.navbar .navbar-collapse{display:flex !important;flex-basis:auto}
.navbar .navbar-nav{flex-direction:row !important;flex-wrap:wrap;gap:.5rem;margin:.4rem 0}
.navbar .nav-link{border:1px solid #c9d0db;border-radius:6px;padding:.45rem 1.1rem !important;font:600 1rem system-ui,sans-serif;color:#2d3a4a !important;background:#fff}
.navbar .nav-link:hover{background:#fdf3d8}
.navbar .nav-link.active{background:#3d6fd6 !important;border-color:#3d6fd6;color:#fff !important}
.navbar-brand{font-weight:700}
.gkey{border:1px solid #e3e6ea;border-radius:8px;background:#fbfcfe;padding:.7rem .9rem;margin:.2rem 0 .8rem}
.gkey-t{font:600 .9rem system-ui,sans-serif;color:#2d3a4a;margin-bottom:.45rem}
.gkey-row{display:flex;align-items:center;gap:.4rem;flex-wrap:wrap;margin-bottom:.45rem}
.gkey-row .gb{font-size:.95rem;padding:.15rem .5rem;min-width:2.6em}
.gkey-end{font:600 .78rem system-ui,sans-serif;color:#667;margin:0 .3rem}
.gkey-s{font-size:.82rem;color:#556;line-height:1.4;margin-top:.3rem}
.headline{text-align:center;padding:1.2rem .5rem .6rem}
.headline .k{font:600 .78rem system-ui,sans-serif;letter-spacing:.14em;text-transform:uppercase;color:#3d6fd6}
.headline .big{font-size:clamp(2.4rem,6vw,3.6rem);line-height:1.1;color:#2d3a4a;margin:.3rem 0}
.headline .sub{color:#556;max-width:760px;margin:0 auto;font-size:.92rem}
.headline .second{margin-top:1rem;padding-top:.9rem;border-top:1px dashed #d8dde6}
.headline .mid{font-size:1.6rem;color:#c9982e}
.tbl tr.hl td{background:#fdf6e3}
.resetbtn{background:#e07a7a;border:none;color:#fff;font:700 .85rem system-ui,sans-serif;letter-spacing:.12em;border-radius:6px;padding:.45rem}
.resetbtn:hover{background:#c75b5b;color:#fff}
.odayears{display:flex;justify-content:center;gap:1.4rem;flex-wrap:wrap;margin:.8rem 0 .4rem}
.odayears div{text-align:center;font:500 .8rem system-ui,sans-serif;color:#556}
