.tbl td{padding:.35rem .4rem;border-bottom:1px solid #eee;vertical-align:top}
.tbl td.num,.tbl th.num{text-align:right;white-space:nowrap}
.tbl td.pn{min-width:260px}.tbl th{white-space:nowrap}
