details.pol[open]>summary{border-bottom:1px solid #eee;background:#f7f9fb}
details.sub{margin:.5rem .9rem .7rem 1.6rem}
details.sub>summary{cursor:pointer;color:#3d6fd6;font-weight:600}
.polbody{padding:.2rem .2rem .4rem}
.kv{margin:.3rem 0}.kv b{font-family:system-ui,sans-serif;font-size:.78rem;text-transform:uppercase;color:#556;letter-spacing:.03em}
.meta{font-weight:400;color:#667;font-size:.85rem}
.q{background:#fff8e6;border-left:3px solid #f2c46d;padding:.4rem .6rem;margin:.5rem 0;font-size:.88rem}
.srcli{margin:.35rem 0;font-size:.86rem}
.note{font-size:.85rem;color:#555}
.meth dt{margin-top:.8rem;color:#3d6fd6;font-family:system-ui,sans-serif;font-size:.9rem}
