"

VB_BLUE   <- value_box_theme(bg = "#5b8def", fg = "#ffffff")
VB_YELLOW <- value_box_theme(bg = "#f2c46d", fg = "#2d3a4a")
VB_RED    <- value_box_theme(bg = "#e07a7a", fg = "#ffffff")
VB_GREEN  <- value_box_theme(bg = "#76bf94", fg = "#ffffff")
VB_GREY   <- value_box_theme(bg = "#eef1f6", fg = "#2d3a4a")

ui <- page_navbar(
  title = "Policy Priorities",
  fillable = FALSE,
  header = tags$head(tags$style(HTML(CSS))),
  nav_panel(
    "Ranking",
    layout_sidebar(sidebar = controls, fillable = FALSE,
    card(card_header("Net value: the best policies listed here vs. the 10 lowest-ranked"),
         plotOutput("budget_top", height = "280px")),
    layout_columns(
      value_box("Top-ranked policy", textOutput("vb_top"), theme = VB_BLUE),
      value_box("Published ranking of this policy", textOutput("vb_n"), theme = VB_YELLOW),
      value_box("Works cited", textOutput("vb_src"), theme = VB_RED),
      col_widths = c(6, 3, 3)
    ),
    card(card_header("Adjusted benefit-cost ratio (middle result and 90% range), all policies in ranked order"),
         p(class = "note", "Each dot is the middle of 1,000 simulated results; the line covers 90% of them. Right of the dashed line, benefits exceed costs. Numbers come from published evidence only."),
         plotOutput("rank_plot", height = "auto")),
    card(card_header("Cost vs. return: where are the best buys?"),
         p(class = "note", "Up = bigger return per dollar. Left = cheaper per year. Colour = how hard it is to put in place (sourced). Top-left is the sweet spot: cheap, high-return, easy."),
         plotOutput("xy_plot", height = "720px")),
    card(card_header("All policies and their numbers"),
         uiOutput("rank_table"))
  )),
  nav_panel(
    "Uncertainty",
    card(card_header("How every policy is graded"),
         p(class = "note", "Grades run from A+ (strongest) to C− (weakest). Each policy gets the grade of its best supporting evidence."),
         rubric_ui),
    card(card_header("How stable is each rank?"),
         p(class = "note", HTML("<b>Why 1,000 simulations?</b> The published evidence gives each policy a <i>range</i>, not one number (free trade: 90 to 2,800). Taking only the middle would hide how sure we are. So we re-run the whole ranking 1,000 times, each time picking every policy's ratio at random from within its published range, and record where it lands. The bar shows the ranks it landed on in the middle 90% of runs; the dot is its typical rank. A short bar means the rank is solid whatever the true number turns out to be; a long bar (like the innovation prizes, whose sources run from 8.9 to 348) means the rank depends on which study is right.")),
         plotOutput("unc_plot", height = "auto")),
    card(card_header("How often does each policy make the top 20?"),
         p(class = "note", "Out of the same 1,000 re-runs, the share in which the policy finished in the top 20. 100% means it made the top 20 in every run, whichever end of its evidence range was drawn: that is a priority you can defend even if some of the studies are too optimistic. A policy near 50% is a coin flip that depends on which studies are right."),
         grade_key(),
         plotOutput("ptop_plot", height = "auto"))
  ),
  nav_panel(
    "Budget",
    card(div(class = "headline",
      div(class = "k", "Development aid budget, 2025"),
      div(class = "big", sprintf("$%.1f billion", ODA[["2025"]])),
      div(class = "sub", "Official development aid from rich-country donors: the money already set aside each year to improve the lives of the world's poorest (OECD; the UN uses the same figures)."),
      div(class = "odayears",
        div(tags$b(sprintf("$%.1fB", ODA[["2023"]])), "2023"),
        div(tags$b(sprintf("$%.1fB", ODA[["2024"]])), "2024"),
        div(class = "cur", tags$b(sprintf("$%.1fB", ODA[["2025"]])), "2025"),
        div(tags$b(sprintf("~$%.0fB", ODA[["2026"]])), "2026 est.")),
      div(class = "sub", HTML("Down 23% in 2025, the steepest drop on record, and the OECD expects a further 5.8% fall in 2026. Against the UN's estimated $4 trillion-a-year funding gap for the development goals, it is about 4%. <span class='small-src'>Sources: OECD preliminary ODA data 2023\u20132025; 2026 is the OECD's projected fall applied to 2025.</span>"))
    )),
    card(card_header("For scale: other budgets, per year, that could be re-allocated"), context_ui),
    card(card_header("Fund the best buys, or the ten worst?"),
      sliderInput("minbcr", "Fund only if the adjusted benefit-cost ratio is above", 1, 50, 1, 0.5, width = "100%"),
      tags$ul(class = "note",
        tags$li(HTML("<b>Best buys:</b> the aid budget goes to the highest-ratio policies above your slider threshold until it runs out. A policy is skipped if it no longer fits, or if it overlaps one already funded (for example, Medicare for All already includes drug-price negotiation).")),
        tags$li(HTML("<b>10 worst, same money:</b> the same amount is split equally across the ten lowest-ratio policies (those with a cost), so both sides spend exactly the same money.")),
        tags$li(HTML("<b>10 best, fully implemented:</b> the ten highest-ratio policies (overlaps counted once) carried out in full: costed ones at their sourced yearly cost times (ratio minus 1); free reforms such as global free trade at their sourced yearly gain, since they have no spending to multiply. This is the like-for-like comparison with the 10 worst, fully implemented.")),
        tags$li(HTML("<b>10 worst, fully implemented:</b> each of the ten lowest-ratio policies is carried out in full at its sourced yearly cost (overlaps counted once). These are mandates on whole economies, so this is the scale they would actually run at."))),
      layout_columns(
        value_box("Best buys: aid spent", textOutput("vb_spent"), theme = VB_GREY),
        value_box("Best buys: net value created", textOutput("vb_benefit"), theme = VB_GREEN),
        value_box("10 worst, same money: net value", textOutput("vb_wspent"), theme = VB_RED),
        value_box("10 worst, fully implemented: net value", textOutput("vb_wbenefit"), theme = VB_RED),
        col_widths = c(3, 3, 3, 3)),
      p(class = "note", textOutput("netnote", inline = TRUE)),
      div(class = "note", style = "background:#fdf6e3;border-left:3px solid #f2c46d;padding:.5rem .7rem;margin-bottom:.6rem", textOutput("fit_note")),
      h5(class = "charttitle", "Net value: the best policies listed here vs. the 10 lowest-ranked"),
      plotOutput("budget_plot", height = "400px")),
    card(card_header(class = "fundhead", textOutput("port_head")),
         p(class = "note", "These are every policy whose adjusted benefit-cost ratio clears the threshold on the slider above, best first. Raise the slider to fund only the strongest buys and watch the list, and the totals above, shrink."),
         uiOutput("port_table")),
    card(card_header("The counterfactual: the 10 lowest-ratio policies"),
         p(class = "note", "These are the ten policies with the lowest adjusted ratios, most of them mandates and spending programmes proposed by governments and international bodies. Funding them instead is the comparison: the same kind of money, spent where the evidence says it destroys value."),
         uiOutput("worst_table"))
  ),
  nav_panel(
    "Policy explorer",
    p(class = "note", "Click a policy to open it; inside, open the summary and the sources. Listed in current rank order."),
    uiOutput("explorer")
  ),
  nav_panel(
    "Deaths",
    card(card_header("Deaths from lost income, and total damage per year"),
         p(class = "note", "Lost income costs lives: about one death per $99.3 million of cost imposed (Broughel & Viscusi). Lower world income raises infant deaths in poor countries by 0.24 to 0.40 per 1,000 births for each 1% fall in income per person (Baird, Friedman & Schady 2011). The two overlap slightly, so they are shown side by side, not added. Policies that raise income save lives instead. Sorted by deaths from lost income."),
         uiOutput("deaths_table"))
  ),
  nav_panel(
    "All sources",
    card(card_body(bib_ui))
  ),
  nav_panel(
    "Methodology",
    card(card_body(
      h3("Methodology"),
      h4("The project"),
      p("This dashboard is the working engine behind two pieces of writing. The first is a book, ", em("Lighthearted Humans: Prosperity Without Pretense"),
        ", which argues that the fastest way to make people richer, healthier and freer is to rank what actually works, fund the best buys, and get government out of the way of everything else. It uses the Copenhagen Consensus idea of comparing policies dollar for dollar, and asks what happens when free trade, sound money, property rights and deregulation are put on the same scale as bed nets and vaccines."),
      p("The second is an academic paper (the thesis) that does the ranking formally. It is a comparative benefit-cost analysis built on published estimates: every benefit-cost ratio comes from other researchers' studies and official reports, put on one scale and ranked. Adding income, feasibility, evidence and cost criteria makes it a multi-criteria decision analysis (MCDA). Everything is built in R."),

      h4("Methodology of the whole analysis"),
      h5("Why this research matters: prioritization"),
      p("Every government, charity and aid agency has a limited budget, and every dollar spent on one policy is a dollar not spent on another. The world's development aid budget was $174 billion in 2025, and the UN's own list of Sustainable Development Goals has 169 targets, so trying to do everything means doing almost nothing well. Some policies return hundreds or thousands of dollars of benefit for every dollar spent; others destroy value. Ranking them on one honest scale shows where the next dollar, or the next repealed rule, does the most good. The question is not \u201cis this a good cause?\u201d but \u201cwhat should come first?\u201d"),
      h5("How this analysis was conducted"),
      p("Forty policies were chosen in four blocks of ten. Climate: five proposals that rank highest in international climate surveys (the UN Peoples' Climate Vote, Dechezlepr\u00eatre et al., the European Investment Bank) and five official proposals (the Green New Deal, the Paris-strength carbon price, the C40 consumption targets, combustion-engine bans and privately funded innovation prizes). Popular: ten policies with majority support in public-opinion surveys. Health: ten programmes rated best buys by the Copenhagen Consensus, the Disease Control Priorities project, the WHO and GiveWell, all scored as government or donor spending. Freedom: two reforms from each of the five areas of the Fraser Institute's Economic Freedom of the World index. For each policy, published studies were collected: peer-reviewed research first, then official estimates, think-tank studies and books. Each policy was given a benefit-cost ratio range from those sources (or built from published numbers where no ratio existed, with the arithmetic shown), a full yearly cost, an evidence grade on a nine-level rubric, and sourced ratings for who benefits and how hard it is to implement. Studies that measured a narrower version of a policy were set aside but listed as counter-evidence. The ranges were then run through 1,000 Monte Carlo simulations to see how stable each rank is, and scored in R, with the benefit-cost ratio always counting in full and optional dials to tilt toward other criteria. The result is the published ranking, which any reader can stress-test with the controls on the left."),
      h4("Every item on this dashboard, explained"),
      tags$dl(class = "meth",
        tags$dt("Benefit-cost ratio (BCR)"),
        tags$dd("Dollars of benefit to society for every dollar of cost, in today's money. Above 1, a policy creates more than it costs; below 0, its harms exceed its benefits. Each policy has a published range, taken from the sources or built from published numbers with the arithmetic shown in the Policy explorer."),
        tags$dt("Adjusted ratio"),
        tags$dd("The published ratio after the evidence-skepticism and discount-rate settings are applied. The dot on each chart is its middle result across 1,000 simulations; the line covers the middle 90%."),
        tags$dt("Evidence grade (A+ to C\u2212)"),
        tags$dd("Each policy gets the grade of its best supporting evidence, using the nine-level rubric on the Uncertainty tab: from several peer-reviewed controlled studies (A+) down to published theory built by analogy (C\u2212)."),
        tags$dt("Evidence skepticism (slider)"),
        tags$dd("How far to pull weaker-graded ratios toward break-even (1:1) in log space. At the left (\u201cAll data\u201d) every published number counts at face value; at the right (\u201cBest data\u201d) a C\u2212 ratio keeps 60% of its size in log terms and an A+ ratio keeps all of it. The middle is the published setting."),
        tags$dt("Discount rate (slider)"),
        tags$dd("How much less a future benefit is worth today. Published ratios mostly use about 5%, so 5% leaves them unchanged. Other rates assume benefits arrive on average 10 years after costs and multiply every ratio by ((1 + 5%) / (1 + r))^10. Because it moves every policy by the same factor, it does not change the order; it changes which policies clear the Budget threshold. Higher expected inflation means a higher discount rate."),
        tags$dt("Tilt dials: who benefits, feasibility, cost"),
        tags$dd("The benefit-cost ratio always counts in full; the ranking is not left to personal weights. Each dial adds a tilt toward one end of a criterion. At the middle it has no effect; at either end it can move a policy's score by up to \u00b10.15 on the 0\u20131 value scale, so one dial can reorder close calls but not overturn a large gap in value. All three dials at full strength together can reorder much of the ranking. There is no separate evidence dial, because the skepticism slider already does that job."),
        tags$dt("Who benefits"),
        tags$dd("Each policy is rated from its sources as benefiting mostly the poor, everyone, or mostly higher incomes. The rating uses the distribution evidence in the sources (for example, trade gains concentrated in low-income countries, or energy mandates that raise costs most for poor households)."),
        tags$dt("Difficulty to implement (easy / moderate / hard)"),
        tags$dd(HTML("Rated from sourced facts with one rule for all 40 policies:<br><b>Easy</b>: one agency, regulator or funder can do it under existing law, and it has been done before (e.g., an agency rule, a philanthropic prize).<br><b>Moderate</b>: needs ordinary legislation in one country, or a sustained funding scale-up, with a working precedent somewhere (e.g., Hong Kong's zero tariffs for unilateral free trade).<br><b>Hard</b>: needs a constitutional amendment, a binding agreement among many countries, or the dismantling of a major institution with no modern precedent.<br>The reason and its source are shown for each policy in the Policy explorer.")),
        tags$dt("Full cost per year"),
        tags$dd("Everything it takes to carry the policy out, in US dollars a year: public spending, administration and enforcement, the compliance spending it forces on households and firms, and output (GDP) lost. The highest credible published cost sits behind the low end of each range. Money moved from one group to another is a transfer worth $1 to the people who receive it; the deadweight loss of the taxes that fund it is a real cost (34 cents per $1 in the mainstream general-equilibrium estimate, about $2 per $1 at the low end)."),
        tags$dt("Rules that destroy value"),
        tags$dd("Rules whose main effect is lost consumer value or output (rationing caps, price controls, mandates and transfer programmes) are scored in net-damage form: the losses are subtracted from the benefits, and the ratio is measured per dollar actually spent or transferred to carry the rule out. A ratio below zero means the rule destroys more than every dollar put into it."),
        tags$dt("Taxes beyond what can be raised"),
        tags$dd("At the peak of the Laffer curve the US can raise at most about 7.4% of GDP in extra tax revenue and the EU-14 about 3.1% (Trabandt & Uhlig 2012). Programmes whose new tax-financed spending is larger than that (the Green New Deal, a global basic income, Medicare for All) use the high published estimate of the tax burden, about $2 of deadweight per $1 raised (Feldstein 1999), at both ends of their range."),
        tags$dt("Lost-income mortality"),
        tags$dd("Lower incomes cost lives: about one statistical death per $99.3 million of cost imposed (Broughel & Viscusi). Valued at the US government's $13.1 million value of a statistical life, each $1 of net income lost carries 13 cents of mortality cost, and each $1 gained saves the same. This step is applied to every policy after its range is drawn. Health programmes, whose benefits are already counted in lives, carry only the mortality cost of the taxes that fund them."),
        tags$dt("Infant deaths in poor countries"),
        tags$dd("When world income falls, poor countries' incomes fall too. Each 1% fall in GDP per person raises infant mortality by 0.24 to 0.40 deaths per 1,000 births (Baird, Friedman & Schady 2011), on about 120 million births a year in low- and middle-income countries. Spillovers from Western economies use 0.6 to 1.4 points of developing-country growth per point of Western growth (World Bank). The Deaths tab lists these alongside deaths from lost income."),
        tags$dt("Carbon values"),
        tags$dd("Avoided climate damage is valued at $36 per tonne of CO2 (Nordhaus) to $66 per tonne (DICE-2023, Barrage & Nordhaus 2024). Cuts made by only some countries are reduced for leakage to the rest of the world, which published estimates put at 12% to 130%."),
        tags$dt("Monte Carlo simulation (1,000 runs)"),
        tags$dd("The sources give each policy a range, not one number. Each range is treated as a 90% interval of a lognormal distribution; the ranking is re-run 1,000 times with every policy's ratio drawn at random from its range. 1,000 runs is enough for the percentages to be stable to about \u00b12 points."),
        tags$dt("Rank range and chance of making the top 20"),
        tags$dd("Across the 1,000 runs, the rank range shows where each policy landed in the middle 90% of runs, and the top-20 chance is the share of runs in which it finished 20th or better. A policy near 100% is a priority whichever of its studies is right."),
        tags$dt("Published ranking and RESET"),
        tags$dd("The published ranking is the order at the default settings (skepticism and tilts in the middle, 5% discount rate). RESET returns every control to those settings; the yellow box on the Ranking tab shows where the current top policy sits in that published ranking."),
        tags$dt("Filters"),
        tags$dd("Policy-area and grade filters hide policies from the charts and tables; ranks are still worked out across all 40."),
        tags$dt("Development aid budget"),
        tags$dd("The headline on the Budget tab is official development aid from rich-country donors (OECD Development Assistance Committee; the UN uses the same figures): $174.3 billion in 2025. The other budgets are shown for scale, as money that could be re-allocated."),
        tags$dt("Best buys vs. the 10 worst, and net value"),
        tags$dd("The best-buys side funds the highest-ratio policies above the slider threshold from the $174.3 billion aid budget, skipping any that no longer fit or that overlap a policy already funded. The counterfactual is shown two ways: the same amount the best buys actually spend split equally across the ten lowest-ratio policies that have a cost (value per dollar), and the ten lowest-ratio policies implemented in full at their sourced yearly cost, with overlapping policies counted once (the scale at which such mandates would actually run). Net value = today's value of all the future benefits the money buys (spending \u00d7 ratio), minus the spending. Reforms that cost nothing, like free trade, add their gains on top for free, so they are not in the green total."),
        tags$dt("Counter-evidence"),
        tags$dd("Studies that measure a narrower or different version of a policy, or use static models that leave out growth effects, are not used in the range. They are still listed under each policy in the Policy explorer with the reason, so every reader can see what was left out.")
      ),
      h4("Caveats"),
      p("Many of these policies have never been tried at full scale, so no study measures them directly; those rely on analogies and carry C grades. Ranges from different studies use different assumptions about discount rates, time horizons and regions. Treat the ranking as a transparent, adjustable argument about priorities, not a forecast."),
      p(em("Source code, data and every citation: the LH_CBA R project.")),
      tags$hr(),
      h3("Methodology (paper version)"),
      p(class = "note", "The full methodology section of the accompanying paper, including formulas, the sensitivity scenarios and the limitations."),
      if (file.exists("methodology.html")) includeHTML("methodology.html")
    ))
  )
)

# ---- Server --------------------------------------------------------------------------
PUB <- run_bca(pol)                                   # the final published ranking (default settings)
PUB_RANK <- setNames(PUB$rank, PUB$id)

server <- function(input, output, session) {

  observeEvent(input$reset, {
    for (id in c("skep", "t_equity", "t_feas", "t_cost")) updateSliderInput(session, id, value = 0.5)
    updateSliderInput(session, "rate", value = 5)
    updateSliderInput(session, "minbcr", value = 1)
    updateSelectizeInput(session, "cats", selected = cats)
    updateCheckboxGroupInput(session, "grades", selected = GRADES)
  })

  res <- reactive({
    tl <- c(equity = (0.5 - input$t_equity) * 2, feasibility = (input$t_feas - 0.5) * 2,
            evidence = 0, cost = (0.5 - input$t_cost) * 2)
    run_bca(pol, skepticism = input$skep, rate = input$rate / 100, tilts = tl)
  })

  shown <- reactive({
    r <- res()
    r
  })
  unrated <- reactive({
    u <- pol[!pol$rated, ]
    u
  })

  output$vb_top <- renderText({ r <- shown(); if (nrow(r)) r$title[1] else "—" })
  output$vb_n   <- renderText({ r <- shown(); if (nrow(r)) paste0("#", PUB_RANK[[as.character(r$id[1])]], " of ", nrow(pol)) else "\u2014" })
  output$vb_src <- renderText(format(length(unique(tolower(paste(src$title, src$year)))), big.mark = ","))

  # ---- signed-log axis helpers
  AX <- c(-1, 0, 0.3, 1, 3, 10, 30, 100, 300, 1000, 3000)
  lab_of <- function(r) paste0(r$rank, ". ", ifelse(nchar(r$title) > 58, paste0(substr(r$title, 1, 57), "…"), r$title))

  row_h <- function(n) max(300, 17 * n + 90)
  # Plain-words labels for the two ends of a chart's horizontal axis, drawn above the plot
  ends_lab <- function(left, right) {
    mtext(left, side = 3, adj = 0, line = 0.5, font = 2, cex = 1.3, col = "#e07a7a")
    mtext(right, side = 3, adj = 1, line = 0.5, font = 2, cex = 1.3, col = "#e07a7a")
  }

  # Spreadsheet-style row shading: alternate bands run from the labels across the
  # whole plot, plus a faint dotted guide on every row, so each line is easy to track.
  zebra <- function(y) {
    x0 <- grconvertX(0, "ndc", "user"); x1 <- par("usr")[2]
    odd <- seq_along(y) %% 2 == 1
    rect(x0, y[odd] - 0.5, x1, y[odd] + 0.5, col = "#eef1f6", border = NA, xpd = NA)
    segments(par("usr")[1], y, x1, y, col = "#c9d2df", lty = 3, lwd = 0.7)
  }


  output$rank_plot <- renderPlot({
    r <- shown(); u <- unrated()
    n <- nrow(r) + nrow(u)
    validate(need(n > 0, "No policies match the filters."))
    labs <- c(lab_of(r), if (nrow(u)) paste0("NR. ", substr(u$title, 1, 57)))
    op <- par(mar = c(4, 1, 1, 1), family = "sans"); on.exit(par(op))
    left <- max(strwidth(labs, units = "inches", cex = 0.78)) + 0.2
    par(mai = c(0.95, left, 0.55, 0.2))
    xr <- range(slog(c(r$bcr_q05, r$bcr_q95, 0.3, 10)), na.rm = TRUE)
    y <- rev(seq_len(n))
    plot(NA, xlim = xr, ylim = c(0.5, n + 0.5), axes = FALSE, xlab = "", ylab = "")
    ends_lab("Destroys value", "Best return")
    mtext("Adjusted benefit-cost ratio: dollars of benefit per $1 spent (log scale; dashed line = 1, break-even)", side = 1, line = 3, cex = 0.9, font = 2, col = "#2d3a4a")
    zebra(y)
    ax <- AX[slog(AX) >= xr[1] - 0.05 & slog(AX) <= xr[2] + 0.05]
    abline(v = slog(ax), col = "#eeeeee"); abline(v = slog(1), lty = 2, col = "grey40")
    axis(1, at = slog(ax), labels = format(ax, big.mark = ",", scientific = FALSE, drop0trailing = TRUE), cex.axis = 0.8)
    k <- nrow(r)
    if (k) {
      cols <- GRADE_COLS[r$grade]
      segments(slog(r$bcr_q05), y[1:k], slog(r$bcr_q95), y[1:k], col = adjustcolor(cols, 0.55), lwd = 3)
      points(slog(r$bcr_median), y[1:k], pch = 19, col = cols, cex = 1.1)
    }
    if (nrow(u)) text(slog(1), y[(k + 1):n], "not rated: no published ratio yet", col = "grey55", cex = 0.72, adj = 0)
    axis(2, at = y, labels = labs, las = 1, cex.axis = 0.78, tick = FALSE, line = -0.8)
  }, height = function() row_h(nrow(shown()) + nrow(unrated())) + 70)

  output$xy_plot <- renderPlot({
    r <- shown()
    validate(need(nrow(r) > 0, "No policies match the filters."))
    op <- par(mai = c(0.8, 0.8, 0.55, 0.2), family = "sans"); on.exit(par(op))
    cx <- log10(1 + pmax(ifelse(is.na(r$cost_bn), 0, r$cost_bn), 0))
    cy <- slog(r$bcr_median)
    xr <- c(-0.15, max(cx, 1) * 1.08); yr <- range(c(cy, 0), na.rm = TRUE) + c(-0.15, 0.2)
    plot(NA, xlim = xr, ylim = yr, axes = FALSE,
         xlab = "Cost per year, $ billions (log scale; 0 = no fiscal cost)", ylab = "Adjusted benefit-cost ratio (log scale)")
    ends_lab("Cheap", "Expensive")
    rect(xr[1] - 1, slog(10), log10(1 + 10), yr[2] + 1, col = "#eaf1fd", border = NA)
    text(xr[1] + 0.02, yr[2] - 0.05, "Best buys: cheap and high-return", adj = c(0, 1), cex = 0.8, col = "#3d6fd6", font = 3)
    xt <- c(0, 1, 10, 100, 1000, 10000, 100000); xt <- xt[log10(1 + xt) <= xr[2]]
    axis(1, at = log10(1 + xt), labels = format(xt, big.mark = ",", scientific = FALSE), cex.axis = 0.8)
    yt <- AX[slog(AX) >= yr[1] & slog(AX) <= yr[2]]
    axis(2, at = slog(yt), labels = format(yt, big.mark = ",", scientific = FALSE, drop0trailing = TRUE), las = 1, cex.axis = 0.8)
    abline(h = slog(1), lty = 2, col = "grey50")
    text(xr[2], slog(1), "break-even", adj = c(1, -0.4), cex = 0.7, col = "grey40")
    cols <- DIFF_COLS[r$difficulty]; cols[is.na(cols)] <- "grey50"
    points(cx, cy, pch = 21, bg = adjustcolor(cols, 0.85), col = "white", cex = 1.6)
    # simple label placement: nudge labels apart vertically within the same x neighbourhood
    ly <- cy; o <- order(cx, cy)
    usr <- par("usr"); gap <- 0.032 * diff(usr[3:4]); xw <- 0.18 * diff(usr[1:2])
    for (it in 1:60) {
      moved <- FALSE
      for (a in seq_along(o)) for (b in seq_along(o)) {
        i <- o[a]; j <- o[b]
        if (i < j && abs(cx[i] - cx[j]) < xw && abs(ly[i] - ly[j]) < gap) {
          d <- (gap - abs(ly[i] - ly[j])) / 2 + 1e-4
          if (ly[i] >= ly[j]) { ly[i] <- ly[i] + d; ly[j] <- ly[j] - d } else { ly[i] <- ly[i] - d; ly[j] <- ly[j] + d }
          moved <- TRUE
        }
      }
      if (!moved) break
    }
    segments(cx, cy, cx + 0.04, ly, col = "grey75", lwd = 0.6)
    text(cx + 0.05, ly, r$short, adj = 0, cex = 0.68, col = "grey15")
    legend("topright", legend = c("Easy", "Moderate", "Hard"), pt.bg = DIFF_COLS, pch = 21, col = "white",
           pt.cex = 1.4, bty = "n", cex = 0.8, title = "Difficulty to implement")
  })

  output$rank_table <- renderUI({
    r <- shown(); u <- unrated()
    rows <- sprintf('<tr><td class="num">%d</td><td class="pn">%s</td><td>%s</td><td>%s</td><td class="num">%s – %s</td><td class="num"><b>%s</b> <span class="meta">(%s – %s)</span></td><td class="num">%s</td><td>%s</td><td>%s</td><td class="num">%.2f</td><td class="num">%s</td></tr>',
                    r$rank, esc(r$title), esc(r$category), badge(r$grade),
                    fmt_bcr(r$bcr_low), fmt_bcr(r$bcr_high), fmt_bcr(r$bcr_median), fmt_bcr(r$bcr_q05), fmt_bcr(r$bcr_q95),
                    fmt_bn(r$cost_bn), esc(tools::toTitleCase(r$difficulty)), esc(WHO_LABEL[r$who_benefits]),
                    r$score, fmt_pct(r$p_top))
    urows <- if (nrow(u)) sprintf('<tr style="color:#888"><td class="num">NR</td><td class="pn">%s</td><td>%s</td><td>%s</td><td class="num" colspan="2">no published ratio yet</td><td class="num">%s</td><td>%s</td><td>%s</td><td></td><td></td></tr>',
                                  esc(u$title), esc(u$category), badge(u$grade), fmt_bn(u$cost_bn),
                                  esc(tools::toTitleCase(u$difficulty)), esc(WHO_LABEL[u$who_benefits])) else character(0)
    HTML(paste0('<div class="tscroll"><table class="tbl"><thead><tr><th class="num">Rank</th><th>Policy</th><th>Area</th><th>Grade</th><th class="num">Published ratio range</th><th class="num">Adjusted ratio (90% range)</th><th class="num">Cost / yr</th><th>Difficulty</th><th>Who benefits</th><th class="num">Score</th><th class="num">Top-20 chance</th></tr></thead><tbody>',
                paste(c(rows, urows), collapse = ""), "</tbody></table></div>"))
  })

  # ---- Uncertainty
  output$unc_plot <- renderPlot({
    r <- shown(); n <- nrow(r)
    validate(need(n > 0, "No policies match the filters."))
    labs <- lab_of(r)
    op <- par(family = "sans"); on.exit(par(op))
    par(mai = c(0.6, max(strwidth(labs, units = "inches", cex = 0.78)) + 0.2, 0.55, 0.2))
    y <- rev(seq_len(n)); cols <- GRADE_COLS[r$grade]
    plot(NA, xlim = c(1, nrow(res())), ylim = c(0.5, n + 0.5), axes = FALSE, xlab = "Rank across 1,000 re-runs (1 = best)", ylab = "")
    ends_lab("Top ranked", "Bottom ranked")
    zebra(y)
    abline(v = c(1, 10, 20, 30, 40, 50), col = "#eeeeee")
    axis(1, at = c(1, 10, 20, 30, 40, 50, nrow(res())), cex.axis = 0.8)
    segments(r$rank_lo, y, r$rank_hi, y, col = adjustcolor(cols, 0.5), lwd = 5, lend = 1)
    points(r$rank_med, y, pch = 19, col = cols)
    axis(2, at = y, labels = labs, las = 1, cex.axis = 0.78, tick = FALSE, line = -0.8)
  }, height = function() row_h(nrow(shown())) + 40)

  output$ptop_plot <- renderPlot({
    r <- shown(); n <- nrow(r)
    validate(need(n > 0, "No policies match the filters."))
    labs <- lab_of(r)
    op <- par(family = "sans"); on.exit(par(op))
    par(mai = c(0.6, max(strwidth(labs, units = "inches", cex = 0.78)) + 0.2, 0.55, 0.4))
    y <- rev(seq_len(n)); cols <- GRADE_COLS[r$grade]
    plot(NA, xlim = c(0, 1.08), ylim = c(0.5, n + 0.5), axes = FALSE, xlab = "Chance of finishing in the top 20", ylab = "")
    ends_lab("Inconsistent", "Consistent")
    zebra(y)
    abline(v = seq(0, 1, 0.25), col = "#eeeeee")
    axis(1, at = seq(0, 1, 0.25), labels = paste0(seq(0, 100, 25), "%"), cex.axis = 0.8)
    rect(0, y - 0.36, r$p_top, y + 0.36, col = cols, border = NA)
    text(r$p_top + 0.01, y, fmt_pct(r$p_top), adj = 0, cex = 0.68, col = "grey30")
    axis(2, at = y, labels = labs, las = 1, cex.axis = 0.78, tick = FALSE, line = -0.8)
  }, height = function() row_h(nrow(shown())) + 40)

  # ---- Budget
  port  <- reactive(portfolio(shown(), input$minbcr))
  worst <- reactive(worst_n(res(), 10))
  money <- function(x) ifelse(x < 0, paste0("\u2212", fmt_bn(-x)), fmt_bn(x))
  # Same money, two ways to spend it (see fund_budget() and fund_worst() in bca_engine.R)
  best_fill  <- reactive(fund_budget(shown(), AVAIL_YR, input$minbcr))
  worst_fill <- reactive(fund_worst(res(), sum(best_fill()$spend), 10))
  best_net  <- reactive(sum(best_fill()$net))
  worst_net <- reactive(sum(worst_fill()$net))
  worst_full <- reactive(fund_worst_full(res(), 10))
  worst_full_net <- reactive(sum(worst_full()$net))
  best_full <- reactive(fund_best_full(res(), 10))
  best_full_net <- reactive(sum(best_full()$net))
  output$vb_spent    <- renderText(fmt_bn(sum(best_fill()$spend)))
  output$vb_benefit  <- renderText(money(best_net()))
  output$vb_wspent   <- renderText(money(worst_net()))
  output$vb_wbenefit <- renderText(money(worst_full_net()))
  output$netnote <- renderText({
    z <- port(); z <- z[z$cost_used == 0, ]
    sprintf("Net value = today's value of all the future benefits the money buys (spending \u00d7 ratio), minus the spending. %d reforms above the threshold cost nothing (including %s), so their gains come on top of the green total for free.",
            nrow(z), paste(head(z$short, 3), collapse = ", "))
  })
  output$fit_note <- renderText({
    f <- best_fill()
    sprintf("Best buys funded from the $%.1fB aid budget (ratio above %s): %s.", AVAIL_YR, input$minbcr,
            if (nrow(f)) paste(f$short, collapse = ", ") else "none fit")
  })
  output$port_head   <- renderText(sprintf("Funded: %d policies with an adjusted ratio above %s", nrow(port()), input$minbcr))

  draw_budget <- function(cols, thin = FALSE) {
    nets <- c(best_net(), best_full_net(), worst_net(), worst_full_net()) / 1000    # $ trillions
    bf <- best_full(); nfree <- sum(bf$spend == 0 & bf$priced)
    labs <- c(sprintf("Best buys, aid budget (ratio > %s): $%.0fB", input$minbcr, sum(best_fill()$spend)),
              sprintf("10 best, fully implemented: $%.0fB/yr + %d free reform%s", sum(bf$spend), nfree, ifelse(nfree == 1, "", "s")),
              sprintf("10 worst, same money: $%.0fB", sum(worst_fill()$spend)),
              sprintf("10 worst, fully implemented: $%.1fT/yr", sum(worst_full()$spend) / 1000))
    left <- max(strwidth(labs, units = "inches", cex = 0.85, font = 2)) + 0.3
    op <- par(mai = c(0.55, left, 0.55, 0.4), family = "sans"); on.exit(par(op))
    xr <- c(min(nets, 0) * 1.15, max(nets, 0) + diff(range(c(nets, 0))) * 0.12); y <- c(4, 3, 2, 1)
    hw <- if (thin) 0.24 else 0.32
    plot(NA, xlim = xr, ylim = c(0.4, 4.6), axes = FALSE, ylab = "", xlab = "Net value, $ trillions per year")
    ends_lab("Value destroyed", "Value created")
    abline(v = pretty(xr), col = "#eeeeee"); abline(v = 0, col = "grey40")
    rect(pmin(0, nets), y - hw, pmax(0, nets), y + hw, col = cols, border = NA)
    text(nets, y, paste0(ifelse(nets < 0, "\u2212", "+"), "$", formatC(abs(nets), format = "f", digits = 1), "T"),
         pos = ifelse(nets >= 0, 4, 2), cex = 0.95, font = 2, col = "grey20", xpd = NA)
    axis(1, at = pretty(xr), labels = paste0(ifelse(pretty(xr) < 0, "\u2212", ""), "$", abs(pretty(xr)), "T"), cex.axis = 0.8)
    axis(2, at = y, labels = labs, las = 1, tick = FALSE, cex.axis = 0.85, font = 2)
  }
  output$budget_plot <- renderPlot({
    nets <- c(best_net(), best_full_net(), worst_net(), worst_full_net())
    draw_budget(ifelse(nets >= 0, PAL["green"], PAL["red"]))
  })
  output$budget_top <- renderPlot(draw_budget(c(PAL["blue"], PAL["yellow"], PAL["red"], PAL["red"]), thin = TRUE))

  budget_rows <- function(f) sprintf('<tr><td class="num">%d</td><td>%s</td><td>%s</td><td class="num">%s</td><td class="num"><b>%s</b></td><td class="num">%s</td><td class="num" style="color:%s">%s</td></tr>',
                    f$rank, esc(f$title), badge(f$grade), fmt_bn(f$cost_bn), fmt_bcr(f$bcr_median),
                    ifelse(f$cost_used > 0, ifelse(f$benefit_bn < 0, paste0("\u2212", fmt_bn(-f$benefit_bn)), fmt_bn(f$benefit_bn)), "\u2014"),
                    ifelse(f$net_bn < 0, "#c75b5b", "#3a8f5c"),
                    ifelse(f$cost_used > 0, money(f$net_bn), "no fiscal cost"))
  budget_table <- function(f) HTML(paste0('<div class="tscroll"><table class="tbl"><thead><tr><th class="num">Rank</th><th>Policy</th><th>Grade</th><th class="num">Cost / yr</th><th class="num">Adjusted ratio</th><th class="num">Benefits / yr</th><th class="num">Net / yr</th></tr></thead><tbody>',
                paste(budget_rows(f), collapse = ""), "</tbody></table></div>"))
  output$deaths_table <- renderUI({
    r <- res(); m <- pol[match(r$id, pol$id), ]
    base <- ifelse(is.na(m$base_bn), m$cost_bn, m$base_bn)
    gain <- suppressWarnings(as.numeric(m$gain_bn))
    net  <- ifelse(!is.na(base) & base > 0, base * (r$bcr_median - 1), ifelse(is.na(gain), 0, gain))
    dead <- ifelse(m$mort_b == 1 & net >= 0, 0, m$income_loss_bn / 99.3 * 1000)
    saved <- ifelse(m$mort_b == 1 & net > 0, net / 99.3 * 1000, 0)
    ilo <- ifelse(is.na(m$emde_loss_lo), 0, m$emde_loss_lo * 0.24 * 119.9 * 1000)
    ihi <- ifelse(is.na(m$emde_loss_hi), 0, m$emde_loss_hi * 0.40 * 119.9 * 1000)
    o <- order(-dead, -ihi, -saved)
    n0 <- function(x) ifelse(x <= 0, "\u2014", formatC(round(x), format = "d", big.mark = ","))
    rows <- sprintf('<tr><td class="num">%d</td><td class="pn">%s</td><td class="num">%s</td><td class="num">%s</td><td class="num">%s</td><td class="num">%s</td><td class="num">%s</td><td class="num" style="color:%s">%s</td></tr>',
                    r$rank[o], esc(r$title[o]), n0(dead[o]), ifelse(ihi[o] > 0, paste0(n0(ilo[o]), " \u2013 ", n0(ihi[o])), "\u2014"),
                    n0(dead[o] * 20), n0(ihi[o] * 20), n0(saved[o]),
                    ifelse(net[o] < 0, "#c75b5b", "#3a8f5c"), money(net[o]))
    HTML(paste0('<div class="tscroll"><table class="tbl"><thead><tr><th class="num">Rank</th><th>Policy</th><th class="num">Deaths a year from lost income</th><th class="num">Infant deaths a year, poor countries</th><th class="num">Deaths over 20 years</th><th class="num">Infant deaths over 20 years (high)</th><th class="num">Lives saved a year from income gained</th><th class="num">Net value per year</th></tr></thead><tbody>',
                paste(rows, collapse = ""), "</tbody></table></div>"))
  })
  output$port_table <- renderUI({ f <- port(); if (!nrow(f)) p("No policy clears that threshold.") else budget_table(f) })
  output$worst_table <- renderUI(budget_table(worst()))

  # ---- Policy explorer: every policy as a drop-down, with nested summary and sources
  src_by_pol <- split(src, src$policy_id)
  output$explorer <- renderUI({
    r <- res()
    ord <- c(r$id, pol$id[!pol$rated])
    rk  <- setNames(r$rank, r$id)
    items <- vapply(ord, function(id) {
      p0 <- pol[pol$id == id, ]; rr <- r[r$id == id, ]
      s_all <- src_by_pol[[as.character(id)]]
      s  <- if (is.null(s_all)) NULL else s_all[s_all$role == "evidence", ]
      cs <- if (is.null(s_all)) NULL else s_all[s_all$role == "counterpoint", ]
      cs_items <- if (is.null(cs) || !nrow(cs)) "" else sprintf("<details class='sub'><summary>Counter-evidence, not used in the range (%d)</summary><ol>%s</ol></details>", nrow(cs),
        paste(sprintf("<li class='srcli'>%s (%s). %s. <em>%s</em>.%s<br><span class='meta'>Why it is not used: %s</span></li>",
          esc(cs$authors), esc(ifelse(is.na(cs$year), "n.d.", cs$year)), esc(cs$title), esc(cs$venue), src_link(cs$url, cs$doi),
          esc(ifelse(is.na(cs$why_excluded), "", cs$why_excluded))), collapse = ""))
      rank_txt <- if (nrow(rr)) paste0("#", rk[[as.character(id)]]) else "NR"
      range_txt <- if (p0$rated) sprintf("published ratio %s – %s", fmt_bcr(p0$bcr_low), fmt_bcr(p0$bcr_high)) else "not rated yet"
      adj_txt <- if (nrow(rr)) sprintf("<div class='kv'><b>Adjusted ratio</b><br>%s (90%% range %s – %s) at your current settings; chance of top 20: %s</div>",
                                       fmt_bcr(rr$bcr_median), fmt_bcr(rr$bcr_q05), fmt_bcr(rr$bcr_q95), fmt_pct(rr$p_top)) else ""
      q_txt <- ""
      src_items <- if (is.null(s) || !nrow(s)) "<p>No sources.</p>" else paste(sprintf(
        "<li class='srcli'>%s (%s). %s. <em>%s</em>. <span class='meta'>[%s]</span>%s%s</li>",
        esc(s$authors), esc(ifelse(is.na(s$year), "n.d.", s$year)), esc(s$title), esc(s$venue),
        esc(ifelse(is.na(TYPE_LABEL[s$type]), s$type, TYPE_LABEL[s$type])),
        ifelse(is.na(s$reported_estimate) | !nzchar(s$reported_estimate), "", paste0("<br><span class='meta'>Reports: ", esc(s$reported_estimate), "</span>")),
        src_link(s$url, s$doi)), collapse = "")
      sprintf(paste0(
        "<details class='pol'><summary>%s · %s <span class='meta'>· %s · %s · %s</span></summary><div class='polbody'>",
        "<details class='sub' open><summary>Summary</summary>",
        "<p>%s</p>%s",
        "<div class='kv'><b>Benefit-cost ratio</b><br>%s</div>",
        "<div class='kv'><b>Evidence grade %s</b><br>%s</div>",
        "<div class='kv'><b>Cost per year: %s</b><br>%s</div>",
        "<div class='kv'><b>Difficulty: %s</b><br>%s</div>",
        "<div class='kv'><b>Who benefits: %s</b><br>%s</div>%s</details>",
        "<details class='sub'><summary>Sources (%d)</summary><ol>%s</ol></details>%s</div></details>"),
        rank_txt, esc(p0$title), esc(p0$category), badge(p0$grade), range_txt,
        esc(p0$summary), adj_txt,
        esc(ifelse(is.na(p0$bcr_basis), "", p0$bcr_basis)),
        badge(p0$grade), esc(p0$grade_reason),
        fmt_bn(p0$cost_bn), esc(p0$cost_basis),
        esc(tools::toTitleCase(p0$difficulty)), esc(p0$difficulty_reason),
        esc(WHO_LABEL[p0$who_benefits]), esc(p0$who_benefits_reason), q_txt,
        if (is.null(s)) 0L else nrow(s), src_items, cs_items)
    }, character(1))
    HTML(paste(items, collapse = "\n"))
  })
}

shinyApp(ui, server)
